#include <iostream>
#define MOD 1000000007LL
using namespace std;

long long mod_pow(int base, int exp);

int main() {
    long long p, k, q;
    cin >> p >> k;
    q = k;
    if (k == 0) {
        cout << mod_pow(p, p - 1);
        return 0;
    }
    if (k == 1) {
        cout << mod_pow(p, p);
        return 0;
    }
    int cycle_length = 1;
    while (q != 1) {
        q = (q * k) % p;
        cycle_length++;
    }
    cout << mod_pow(p, (p - 1) / cycle_length);
    return 0;
}

long long mod_pow(int base, int exponent) {
    long long res = 1;
    long long b = base;
    long long e = exponent;
    while (e > 0) {
        if (e & 1) {
            res = (res * b) % MOD;
        }
        b = (b * b) % MOD;
        e >>= 1;
    }
    return res;
}
